import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    strings = data[1:]

    if n == 2:
        res = ['P', 'S']
        print("".join(res))
        return

    long_strings = [s for s in strings if len(s) == n - 1]
    cand1 = long_strings[0]
    cand2 = long_strings[1]

    def try_build(prefix, suffix):
        full = prefix + suffix[-1]
        used = {i: False for i in range(len(strings))}
        assigned = []

        for i, s in enumerate(strings):
            if s == prefix and not used[i]:
                if len(s) == n - 1:
                    assigned.append(('P', i))
                    used[i] = True
                else:
                    pass
            elif s == suffix and not used[i]:
                if len(s) == n - 2:
                    assigned.append(('S', i))
                    used[i] = True
                else:
                     pass

        counts = {}
        for i, s in enumerate(strings):
            if s not in counts:
                counts[s] = []
            counts[s].append(i)

        p_count = [0] * (n - 1)
        s_count = [0] * (n - 1)

        for i, s in enumerate(strings):
            l = len(s)
            if s == prefix[:l]:
                p_count[l-1] += 1
            if s == suffix[l-1:]:
                s_count[l-1] += 1

        if sum(p_count) != n - 1 or sum(s_count) != n - 1:
            return None

        res = [''] * len(strings)
        p_used = [False] * (n - 1)
        s_used = [False] * (n - 1)

        for i, s_val in enumerate(strings):
            l = len(s_val)
            is_p = (s_val == full[:l])
            is_s = (s_val == full[l:])

            if is_p and not p_used[l-1]:
                res[i] = 'P'
                p_used[l-1] = True
            elif is_s and not s_used[l-1]:
                res[i] = 'S'
                s_used[l-1] = True
            elif is_p and is_s:
                if not p_used[l-1]:
                    res[i] = 'P'
                    p_used[l-1] = True
                else:
                    res[i] = 'S'
                    s_used[l-1] = True
            else:
                return None

        if ''.join(res).count('P') == n - 1 and ''.join(res).count('S') == n - 1:
            return "".join(res)
        return None

    ans = try_build(cand1, cand2)
    if ans:
        print(ans)
        return

    ans = try_build(cand2, cand1)
    if ans:
        print(ans)
        return

solve()
